class MemoryStream(WritableStream):
    def __init__(self):
        self.data = ""
    def write(self, s):
        self.data += s
        return len(s)
stream = MemoryStream()
assert isinstance(stream, WritableStream)
assert stream.write("hello") == 5
assert stream.data == "hello"
assert stream.write(" world") == 6
